package eu.btimpl.languagelearner.attempts;

import java.time.Instant;
import java.util.UUID;

/**
 * One answer of a student. The word is copied here, so the attempt stays understandable after the
 * teacher edits the sheet.
 *
 * @param id generated by the client; saving the same id twice keeps one attempt
 * @param studentId database id of the student
 * @param answeredAt the time of the client
 * @param receivedAt the time of the server
 */
public record Attempt(
    UUID id,
    long studentId,
    String deckId,
    String deckName,
    String wordId,
    String english,
    String hungarian,
    Mode mode,
    Outcome outcome,
    Instant answeredAt,
    Instant receivedAt) {}
